describe("CompositeDiscountPolicy", () => {
  it("rejects empty policies array", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow();
  });

  describe("sum mode", () => {
    it("sums discount amounts from all policies on the original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed = 200 → sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps individual negative discounts to 0 before summing", () => {
      const negative = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negative, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // -50 clamped to 0, + 100 = 100
      expect(composite.computeDiscountCents(500)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies each policy to the remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 10% of 1000 = 100 → remaining 900, 10% of 900 = 90 → total = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("order matters in chain mode", () => {
      const a = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(10)],
        "chain",
      );
      const b = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // a: fixed 200 off 1000 → remaining 800, 10% of 800 = 80 → total 280
      // b: 10% of 1000 = 100 → remaining 900, fixed 200 → total 300
      expect(a.computeDiscountCents(1000)).toBe(280);
      expect(b.computeDiscountCents(1000)).toBe(300);
    });

    it("stops chaining when remaining is exhausted", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // 800 off 1000 → remaining 200, min(800, 200) = 200 → total 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child discounts to 0 in chain mode", () => {
      const negative = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negative, new FixedAmountDiscountPolicy(50)],
        "chain",
      );
      // negative clamped to 0 → remaining still 500, then fixed 50
      expect(composite.computeDiscountCents(500)).toBe(50);
    });
  });

  it("defaults to sum mode", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

