    cart.add(makeProduct({ id: "a" }), 1);
    cart.add(makeProduct({ id: "b" }), 1);
    const checker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "out of stock" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });

  it("checkout with all collaborators", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      shippingCalculator: new FlatShippingCalculator(399),
      region: "US-CA",
    });
    cart.add(makeProduct({ id: "item1" }), 3);
    const result = await cart.checkout({
      priceFetcher: fetcher,
      inventoryChecker: checker,
      asyncTaxProvider: provider,
    });
    // After refresh: unitPrice=2000, qty=3 → subtotal=6000
    // discount: 10% of 6000 = 600
    // discounted: 5400
    // tax: 8% of 5400 = 432
    // shipping: 399
    expect(result.totals.subtotalCents).toBe(6000);
    expect(result.totals.discountCents).toBe(600);
    expect(result.totals.taxCents).toBe(432);
    expect(result.totals.shippingCents).toBe(399);
    expect(result.totals.totalCents).toBe(5400 + 432 + 399);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("item1");
    expect(checker.check).toHaveBeenCalledWith("item1", 3);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects negative percent", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0%", () => {
    const policy = new PercentageDiscountPolicy(0);
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100%", () => {
    const policy = new PercentageDiscountPolicy(100);
    expect(policy.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% of 10000", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(10000)).toBe(1000);
  });

  it("floors fractional cents", () => {
    const policy = new PercentageDiscountPolicy(33);
    // 33% of 100 = 33.0
    expect(policy.computeDiscountCents(100)).toBe(33);
    // 33% of 101 = 33.33 → floor to 33
    expect(policy.computeDiscountCents(101)).toBe(33);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(-1000)).toBe(0);
  });

  it("handles very large subtotal", () => {
    const policy = new PercentageDiscountPolicy(15);
    expect(policy.computeDiscountCents(99999999)).toBe(Math.floor(99999999 * 15 / 100));
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amount", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amount", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts zero", () => {
    const policy = new FixedAmountDiscountPolicy(0);
    expect(policy.computeDiscountCents(500)).toBe(0);
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(1000)).toBe(500);
  });

  it("caps at subtotal when amount exceeds subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(2000);
    expect(policy.computeDiscountCents(1000)).toBe(1000);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policies array", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow();
  });

  describe("sum mode", () => {
    it("sums discount amounts from all policies on the original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed = 200 → sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps individual negative discounts to 0 before summing", () => {
      const negative = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negative, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // -50 clamped to 0, + 100 = 100
      expect(composite.computeDiscountCents(500)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies each policy to the remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 10% of 1000 = 100 → remaining 900, 10% of 900 = 90 → total = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("order matters in chain mode", () => {
      const a = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(10)],
        "chain",
      );
      const b = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // a: fixed 200 off 1000 → remaining 800, 10% of 800 = 80 → total 280
      // b: 10% of 1000 = 100 → remaining 900, fixed 200 → total 300
      expect(a.computeDiscountCents(1000)).toBe(280);
      expect(b.computeDiscountCents(1000)).toBe(300);
    });

    it("stops chaining when remaining is exhausted", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // 800 off 1000 → remaining 200, min(800, 200) = 200 → total 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child discounts to 0 in chain mode", () => {
      const negative = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negative, new FixedAmountDiscountPolicy(50)],
        "chain",
      );
      // negative clamped to 0 → remaining still 500, then fixed 50
      expect(composite.computeDiscountCents(500)).toBe(50);
    });
  });

  it("defaults to sum mode", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

