import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import {
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
} from "../src/pricing.ts";
import { RegionalTaxCalculator } from "../src/tax.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, ...overrides };
}

describe("Cart line management", () => {
  it("adds a product", () => {
    const cart = new Cart();
    cart.add(makeProduct(), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantities on duplicate add", () => {
    const cart = new Cart();
    cart.add(makeProduct(), 1);
    cart.add(makeProduct(), 3);
    expect(cart.itemCount).toBe(4);
  });

  it("rejects non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(makeProduct(), 0)).toThrow(RangeError);
    expect(() => cart.add(makeProduct(), -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(makeProduct(), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const cart = new Cart();
    expect(() => cart.add(makeProduct({ unitPriceCents: -1 }), 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    const cart = new Cart();
    cart.add(makeProduct(), 1);
    expect(cart.remove("p1")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updates quantity", () => {
    const cart = new Cart();
    cart.add(makeProduct(), 2);
    cart.updateQuantity("p1", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity(0) removes the product", () => {
    const cart = new Cart();
    cart.add(makeProduct(), 2);
    cart.updateQuantity("p1", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity rejects negative", () => {
    const cart = new Cart();
    cart.add(makeProduct(), 1);
    expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer", () => {
    const cart = new Cart();
    cart.add(makeProduct(), 1);
    expect(() => cart.updateQuantity("p1", 1.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 5)).toThrow();
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(makeProduct(), 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(makeProduct(), 1);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("p1");
    // Mutating snapshot does not affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart pricing pipeline", () => {
  it("computes subtotal correctly", () => {
    const cart = new Cart();
    cart.add(makeProduct({ id: "a", unitPriceCents: 1000 }), 2);
    cart.add(makeProduct({ id: "b", unitPriceCents: 500 }), 3);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(3500);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("applies discount policy", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(makeProduct({ unitPriceCents: 2000 }), 1);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(2000);
    expect(t.discountCents).toBe(500);
    expect(discount.computeDiscountCents).toHaveBeenCalledWith(2000);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 9999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -100,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
    cart.totals();
    // subtotal 1000, discount 200, taxable = 800
    expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
  });

  it("shipping receives lines and discounted subtotal", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 300,
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
    cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      700, // 1000 - 300
    );
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: { computeDiscountCents: () => 100 },
      taxCalculator: { computeTaxCents: () => 50 },
      shippingCalculator: { computeShippingCents: () => 200 },
    });
    cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
    const t = cart.totals();
    // subtotal 1000, discount 100, discounted 900, tax 50, shipping 200
    expect(t.totalCents).toBe(900 + 50 + 200);
  });

  it("uses custom region for tax", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(makeProduct(), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: () => -50,
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(makeProduct(), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: () => -99,
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(makeProduct(), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

describe("Cart with real policies integration", () => {
  it("percentage discount + regional tax + flat shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
