    const cart = new Cart();
    cart.add(makeProduct({ id: "y" }), 5);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 2,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("y");
      expect(ie.requested).toBe(5);
      expect(ie.available).toBe(2);
    }
  });

  it("passes when inventory check is available", async () => {
    const cart = new Cart();
    cart.add(makeProduct(), 1);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(1000);
  });

  it("uses asyncTaxProvider for tax", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
