toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine, Product } from "../src/product.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, ...overrides };
}

function makeLine(product: Partial<Product> = {}, quantity = 1): CartLine {
  return { product: makeProduct(product), quantity };
}

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 for positive taxable", () => {
    expect(calc.computeTaxCents(5000, "US")).toBe(0);
  });

  it("returns 0 for zero taxable", () => {
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  it("rejects default rate < 0", () => {
    expect(() => new RegionalTaxCalculator({}, -0.1)).toThrow(RangeError);
  });

  it("rejects default rate > 1", () => {
    expect(() => new RegionalTaxCalculator({}, 1.5)).toThrow(RangeError);
  });

  it("rejects NaN default rate", () => {
    expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
  });

  it("rejects region rate < 0", () => {
    expect(() => new RegionalTaxCalculator({ US: -0.01 })).toThrow(RangeError);
  });

  it("rejects region rate > 1", () => {
    expect(() => new RegionalTaxCalculator({ US: 1.01 })).toThrow(RangeError);
  });

  it("rejects NaN region rate", () => {
    expect(() => new RegionalTaxCalculator({ US: NaN })).toThrow(RangeError);
  });

  it("uses region-specific rate", () => {
    const calc = new RegionalTaxCalculator({ "US-CA": 0.0875, "US-TX": 0.0625 });
    // 8.75% of 10000 = 875
    expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
  });

  it("falls back to default rate for unknown region", () => {
    const calc = new RegionalTaxCalculator({ US: 0.08 }, 0.05);
    // 5% of 2000 = 100
    expect(calc.computeTaxCents(2000, "FR")).toBe(100);
  });

  it("falls back to 0 when no default specified and region unknown", () => {
    const calc = new RegionalTaxCalculator({ US: 0.08 });
    expect(calc.computeTaxCents(2000, "FR")).toBe(0);
  });

  it("floors fractional tax", () => {
    const calc = new RegionalTaxCalculator({ US: 0.07 });
    // 7% of 999 = 69.93 → floor to 69
    expect(calc.computeTaxCents(999, "US")).toBe(69);
  });

  it("returns 0 for zero taxable", () => {
    const calc = new RegionalTaxCalculator({ US: 0.1 });
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", () => {
    const calc = new RegionalTaxCalculator({ US: 0.1 });
    expect(calc.computeTaxCents(-500, "US")).toBe(0);
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax from provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(10000, "US")).toBe(1000);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("floors fractional result", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.07),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 7% of 999 = 69.93 → 69
    expect(await calc.computeTaxCents(999, "US")).toBe(69);
  });

  it("returns 0 for zero taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it("throws on rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws on negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws on NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network error")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow("network error");
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weight × quantity", () => {
    const lines: CartLine[] = [
      makeLine({ weightGrams: 100 }, 2),
      makeLine({ weightGrams: 300 }, 1),
    ];
    expect(totalLineWeightGrams(lines)).toBe(500);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [makeLine({}, 3)];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty array", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

