toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine, Product } from "../src/product.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, ...overrides };
}

function makeLine(product: Partial<Product> = {}, quantity = 1): CartLine {
  return { product: makeProduct(product), quantity };
}

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine()], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 99.9)).toThrow(RangeError);
  });

  it("returns flat fee for normal cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([makeLine()], 1000)).toBe(599);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([], 1000)).toBe(0);
  });

  it("returns 0 when subtotal meets free-over threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([makeLine()], 5000)).toBe(0);
  });

  it("returns 0 when subtotal exceeds free-over threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([makeLine()], 6000)).toBe(0);
  });

  it("returns flat fee when subtotal is below free-over threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([makeLine()], 4999)).toBe(599);
  });

  it("accepts zero flatCents", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([makeLine()], 1000)).toBe(0);
  });

  it("accepts zero freeOverCents (always free for non-empty)", () => {
    const calc = new FlatShippingCalculator(500, 0);
    expect(calc.computeShippingCents([makeLine()], 0)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets array", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow();
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 1.5 }]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 100 }], -1),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 100 }], 1.5),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
    ]);
    expect(calc.computeShippingCents([], 1000)).toBe(0);
  });

  it("returns 0 when total weight is 0", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
    ]);
    // Product without weightGrams → treated as 0
    expect(calc.computeShippingCents([makeLine()], 1000)).toBe(0);
  });

  it("selects the correct bracket for weight within first bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    const lines = [makeLine({ weightGrams: 200 }, 1)];
    expect(calc.computeShippingCents(lines, 0)).toBe(300);
  });

  it("selects second bracket when weight exceeds first boundary", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    const lines = [makeLine({ weightGrams: 501 }, 1)];
    expect(calc.computeShippingCents(lines, 0)).toBe(600);
  });

  it("uses bracket at exact boundary", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    const lines = [makeLine({ weightGrams: 500 }, 1)];
    expect(calc.computeShippingCents(lines, 0)).toBe(300);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      999,
    );
    const lines = [makeLine({ weightGrams: 1500 }, 1)];
    expect(calc.computeShippingCents(lines, 0)).toBe(999);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    const lines = [makeLine({ weightGrams: 2000 }, 1)];
    expect(calc.computeShippingCents(lines, 0)).toBe(600);
  });

  it("sorts brackets internally regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 500, costCents: 300 },
    ]);
    const lines = [makeLine({ weightGrams: 400 }, 1)];
    expect(calc.computeShippingCents(lines, 0)).toBe(300);
  });

  it("sums weights across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    const lines = [
      makeLine({ id: "a", weightGrams: 200 }, 2), // 400g
      makeLine({ id: "b", weightGrams: 150 }, 1), // 150g = 550g total
    ];
    expect(calc.computeShippingCents(lines, 0)).toBe(600);
  });
});

