describe("Cart.checkout()", () => {
  it("returns totals and lines for basic checkout", async () => {
    const cart = new Cart();
    cart.add(makeProduct({ unitPriceCents: 500 }), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(makeProduct({ id: "a", unitPriceCents: 100 }), 1);
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const result = await cart.checkout({ priceFetcher: fetcher });
    expect(result.totals.subtotalCents).toBe(999);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(makeProduct({ id: "x" }), 3);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "discontinued" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("x");
      expect(ie.requested).toBe(3);
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(makeProduct({ id: "y" }), 5);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 2,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("y");
      expect(ie.requested).toBe(5);
      expect(ie.available).toBe(2);
    }
  });

  it("passes when inventory check is available", async () => {
    const cart = new Cart();
    cart.add(makeProduct(), 1);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(1000);
  });

  it("uses asyncTaxProvider for tax", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(200),
      region: "US",
    });
    cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // subtotal 1000, discount 200, discounted 800, 10% tax = 80
    expect(result.totals.taxCents).toBe(80);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("async checkout composes discount + async tax + shipping", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(20),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(makeProduct({ unitPriceCents: 5000 }), 2);
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // subtotal: 10000
    // discount: 20% of 10000 = 2000
    // discounted: 8000
    // tax: 5% of 8000 = 400
    // shipping: 500
    expect(result.totals.subtotalCents).toBe(10000);
    expect(result.totals.discountCents).toBe(2000);
    expect(result.totals.taxCents).toBe(400);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(8000 + 400 + 500);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(makeProduct(), 1);
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    const cart = new Cart();
    cart.add(makeProduct(), 1);
    await expect(
      cart.checkout({ asyncTaxProvider: provider }),
    ).rejects.toThrow("tax service down");
  });

  it("first failing inventory line throws", async () => {
    const cart = new Cart();
    cart.add(makeProduct({ id: "a" }), 1);
    cart.add(makeProduct({ id: "b" }), 1);
    const checker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "out of stock" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });

  it("checkout with all collaborators", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      shippingCalculator: new FlatShippingCalculator(399),
      region: "US-CA",
    });
    cart.add(makeProduct({ id: "item1" }), 3);
    const result = await cart.checkout({
      priceFetcher: fetcher,
      inventoryChecker: checker,
      asyncTaxProvider: provider,
    });
    // After refresh: unitPrice=2000, qty=3 → subtotal=6000
    // discount: 10% of 6000 = 600
    // discounted: 5400
    // tax: 8% of 5400 = 432
    // shipping: 399
    expect(result.totals.subtotalCents).toBe(6000);
    expect(result.totals.discountCents).toBe(600);
    expect(result.totals.taxCents).toBe(432);
    expect(result.totals.shippingCents).toBe(399);
    expect(result.totals.totalCents).toBe(5400 + 432 + 399);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("item1");
    expect(checker.check).toHaveBeenCalledWith("item1", 3);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });
});

